<?php
declare(strict_types=1);
$sessionPath='/home3/crist668/php_sessions_patrona';
if(!is_dir($sessionPath)||!is_writable($sessionPath)){http_response_code(503);exit('Sesiones no disponibles');}
session_save_path($sessionPath);session_start();
if(empty($_SESSION['patrona_admin_id'])){header('Location: admin.php');exit;}
if(empty($_SESSION['patrona_csrf']))$_SESSION['patrona_csrf']=bin2hex(random_bytes(32));
function te($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function topbar_url(string $url):bool{return $url===''||$url==='#'||(filter_var($url,FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true));}
$error='';$notice=(string)($_SESSION['topbar_notice']??'');unset($_SESSION['topbar_notice']);
$config=[];$items=[];
try{
 $cfg=require __DIR__.'/class/conexion_local.php';
 if(!is_array($cfg)||($cfg['db']??'')!=='crist668_colegio_patrona_laflorida')throw new RuntimeException('Base no autorizada.');
 mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
 $db=new mysqli($cfg['host'],$cfg['user'],$cfg['pass'],$cfg['db']);$db->set_charset('utf8mb4');
 $q=$db->prepare("SELECT * FROM seccion WHERE id_institucion=2 AND nombre_interno='topbar' LIMIT 1");$q->execute();$section=$q->get_result()->fetch_assoc();
 if(!$section)throw new RuntimeException('No existe el contenedor topbar.');
 $sid=(int)$section['id_seccion'];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals((string)$_SESSION['patrona_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Sesión vencida. Recarga la página.');
  if(($section['editable']??'no')!=='si')throw new RuntimeException('Este contenedor no está habilitado para edición.');
  $action=(string)($_POST['accion']??'');$id=max(0,(int)($_POST['id_item']??0));
  if($action==='config'){
   $values=['titulo_bloque'=>trim((string)($_POST['nombre_colegio']??'')),'texto'=>trim((string)($_POST['mensaje']??''))];
   foreach($values as $key=>$value)if(mb_strlen($value)>240)throw new RuntimeException('El texto es demasiado largo.');
   $db->begin_transaction();
   try{foreach($values as $key=>$value){$q=$db->prepare('DELETE FROM seccion_config WHERE id_seccion=? AND clave=?');$q->bind_param('is',$sid,$key);$q->execute();$q=$db->prepare('INSERT INTO seccion_config(id_seccion,clave,valor) VALUES(?,?,?)');$q->bind_param('iss',$sid,$key,$value);$q->execute();}$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}
  }elseif(in_array($action,['save','delete','toggle'],true)){
   if($id){$q=$db->prepare('SELECT * FROM seccion_item WHERE id_item=? AND id_seccion=?');$q->bind_param('ii',$id,$sid);$q->execute();$old=$q->get_result()->fetch_assoc();if(!$old)throw new RuntimeException('Elemento no encontrado.');}
   if($action==='delete'){$q=$db->prepare('DELETE FROM seccion_item WHERE id_item=? AND id_seccion=?');$q->bind_param('ii',$id,$sid);$q->execute();}
   elseif($action==='toggle'){$next=$old['visible']==='si'?'no':'si';$q=$db->prepare('UPDATE seccion_item SET visible=? WHERE id_item=? AND id_seccion=?');$q->bind_param('sii',$next,$id,$sid);$q->execute();}
   else{
    $kind=(string)($_POST['tipo']??'');$valid=['direccion','telefono','correo','enlace','instagram','facebook','youtube','linkedin','x'];
    if(!in_array($kind,$valid,true))throw new RuntimeException('Tipo de elemento no válido.');
    $label=trim((string)($_POST['titulo']??''));$value=trim((string)($_POST['url']??''));
    if($label===''||mb_strlen($label)>120||mb_strlen($value)>500)throw new RuntimeException('Nombre o valor inválido.');
    if($kind==='correo'&&!filter_var($value,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Introduce un correo válido.');
    if($kind==='telefono'&&!preg_match('/^[+0-9 ()-]{6,30}$/',$value))throw new RuntimeException('Introduce un teléfono válido.');
    if(!in_array($kind,['direccion','telefono','correo'],true)&&!topbar_url($value))throw new RuntimeException('Introduce una URL http(s) válida.');
    $visible=($_POST['visible']??'si')==='no'?'no':'si';$orden=max(1,(int)($_POST['orden']??1));
    if($id){$q=$db->prepare('UPDATE seccion_item SET etiqueta=?,titulo=?,url=?,visible=?,orden=? WHERE id_item=? AND id_seccion=?');$q->bind_param('ssssiii',$kind,$label,$value,$visible,$orden,$id,$sid);}
    else{$q=$db->prepare('INSERT INTO seccion_item(id_seccion,etiqueta,titulo,url,visible,orden) VALUES(?,?,?,?,?,?)');$q->bind_param('issssi',$sid,$kind,$label,$value,$visible,$orden);}
    $q->execute();
   }
  }else throw new RuntimeException('Acción no permitida.');
  $_SESSION['topbar_notice']='Cambios guardados correctamente.';header('Location: editar_topbar.php');exit;
 }
 $q=$db->prepare('SELECT clave,valor FROM seccion_config WHERE id_seccion=?');$q->bind_param('i',$sid);$q->execute();foreach($q->get_result()->fetch_all(MYSQLI_ASSOC) as $row)$config[$row['clave']]=$row['valor'];
 $q=$db->prepare('SELECT * FROM seccion_item WHERE id_seccion=? ORDER BY orden,id_item');$q->bind_param('i',$sid);$q->execute();$items=$q->get_result()->fetch_all(MYSQLI_ASSOC);
}catch(Throwable $e){error_log('Editor topbar Patrona: '.$e->getMessage());$error=$e->getMessage();}
$edit=null;foreach($items as $item)if((int)$item['id_item']===(int)($_GET['item']??0))$edit=$item;
$types=['direccion'=>'Dirección','telefono'=>'Teléfono','correo'=>'Correo electrónico','enlace'=>'Enlace destacado','instagram'=>'Instagram','facebook'=>'Facebook','youtube'=>'YouTube','linkedin'=>'LinkedIn','x'=>'X (Twitter)'];
?>
