<section class="card"><div class="toolbar"><div><h2>Datos de contacto y redes sociales</h2><p class="muted">Puedes agregar, editar, ocultar, ordenar o eliminar cada elemento.</p></div><button class="btn" type="button" id="add-topbar-item"><i class="bi bi-plus-circle"></i> Agregar elemento</button></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Tipo</th><th>Nombre</th><th>Valor / enlace</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=(int)$i['orden']?></td><td><?=te($types[$i['etiqueta']??'']??'Otro')?></td><td><strong><?=te($i['titulo'])?></strong></td><td><?=te(mb_strimwidth((string)$i['url'],0,48,'…'))?></td><td><span class="pill <?=($i['visible']??'si')==='si'?'':'off'?>"><?=($i['visible']??'si')==='si'?'Visible':'Oculto'?></span></td><td><div class="actions"><a href="?item=<?=(int)$i['id_item']?>" title="Editar" aria-label="Editar <?=te($i['titulo'])?>"><i class="bi bi-pencil-square"></i></a><form method="post"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="toggle"><input type="hidden" name="id_item" value="<?=(int)$i['id_item']?>"><button title="Cambiar visibilidad" aria-label="Cambiar visibilidad"><i class="bi bi-eye<?=($i['visible']??'si')==='si'?'':'-slash'?>"></i></button></form><form method="post" onsubmit="return confirm('¿Eliminar este elemento de la barra superior?')"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="delete"><input type="hidden" name="id_item" value="<?=(int)$i['id_item']?>"><button title="Eliminar" aria-label="Eliminar"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="6" class="muted">Todavía no hay elementos. Agrega una dirección, teléfono, correo o red social.</td></tr><?php endif;?></tbody></table></div></section>
<dialog class="editor-dialog" id="form-elemento" aria-labelledby="editor-dialog-title"><form method="post"><div class="editor-dialog-header"><h2 id="editor-dialog-title"><?=$edit?'Editar elemento':'Agregar elemento'?></h2><button type="button" class="dialog-close" id="close-editor-dialog" aria-label="Cerrar"><i class="bi bi-x-lg"></i></button></div><div class="editor-dialog-body"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="save"><input type="hidden" name="id_item" value="<?=(int)($edit['id_item']??0)?>"><div class="grid"><label class="field">Tipo de elemento<span class="type-picker"><span class="type-logo" id="type-logo" aria-hidden="true"><i class="bi bi-geo-alt"></i></span><select name="tipo" id="tipo" required><?php foreach($types as $key=>$label):?><option value="<?=te($key)?>" <?=($edit['etiqueta']??'')===$key?'selected':''?>><?=te($label)?></option><?php endforeach;?></select></span></label><label class="field">Nombre visible<input name="titulo" maxlength="120" required placeholder="Ej.: Instagram, Secretaría, Dirección" value="<?=te($edit['titulo']??'')?>"></label><label class="field">Dirección, teléfono, correo o URL<input name="url" maxlength="500" id="valor" placeholder="https://... o contacto@colegio.cl" value="<?=te($edit['url']??'')?>"></label><label class="field">Orden<input type="number" name="orden" min="1" value="<?=(int)($edit['orden']??count($items)+1)?>"></label><div class="field visibility-field"><span>Visibilidad</span><label class="visibility-switch"><input type="checkbox" id="item-visible-check" <?=($edit['visible']??'si')==='si'?'checked':''?>><span class="visibility-track" aria-hidden="true"></span><span id="visibility-label">Visible en el sitio</span></label><input type="hidden" name="visible" id="item-visible-value" value="<?=te($edit['visible']??'si')?>"></div></div><p class="muted">Para redes sociales y enlaces, utiliza una URL completa con https://. Para dirección, escribe la ubicación; para teléfono, el número; para correo, la dirección electrónica.</p></div><div class="editor-dialog-footer"><button class="btn secondary" type="button" id="cancel-editor-dialog">Cancelar</button><button class="btn" type="submit"><i class="bi bi-check2-circle"></i> Guardar elemento</button></div></form></dialog>
<?php endif;?></div></main></div></div><script defer src="assets/admin/js/patrona-sidebar.js?v=1"></script><script>
(()=>{'use strict';
const shell=document.getElementById('editor-admin-shell'),toggle=document.getElementById('editor-sidebar-toggle'),dialog=document.getElementById('form-elemento'),add=document.getElementById('add-topbar-item');
if(toggle&&shell)toggle.addEventListener('click',()=>{const collapsed=shell.classList.toggle('editor-collapsed');toggle.setAttribute('aria-expanded',String(!collapsed));toggle.setAttribute('aria-label',collapsed?'Expandir menú lateral':'Contraer menú lateral');toggle.title=collapsed?'Expandir menú lateral':'Contraer menú lateral';});
if(!dialog)return;
const form=dialog.querySelector('form'),type=form.elements.namedItem('tipo'),visible=document.getElementById('item-visible-check'),visibleValue=document.getElementById('item-visible-value'),visibleLabel=document.getElementById('visibility-label'),logo=document.getElementById('type-logo');
const icons={direccion:'geo-alt-fill',telefono:'telephone-fill',correo:'envelope-fill',enlace:'box-arrow-up-right',instagram:'instagram',facebook:'facebook',youtube:'youtube',linkedin:'linkedin',x:'twitter-x'};
function updateIcon(){const icon=icons[type.value]||'link-45deg';logo.innerHTML='<i class="bi bi-'+icon+'"></i>';logo.title=type.options[type.selectedIndex]?.text||'';}
function updateVisibility(){visibleValue.value=visible.checked?'si':'no';visibleLabel.textContent=visible.checked?'Visible en el sitio':'Oculto en el sitio';form.querySelectorAll('.item-edit-field').forEach(el=>el.classList.toggle('dialog-muted-fields',!visible.checked));}
type.addEventListener('change',updateIcon);visible.addEventListener('change',updateVisibility);
form.querySelectorAll('.field').forEach(el=>{if(!el.classList.contains('visibility-field'))el.classList.add('item-edit-field');});
updateIcon();updateVisibility();
const close=()=>{dialog.close();if(new URLSearchParams(location.search).has('item'))location.replace('editar_topbar.php');};
document.getElementById('close-editor-dialog')?.addEventListener('click',close);document.getElementById('cancel-editor-dialog')?.addEventListener('click',close);
dialog.addEventListener('click',e=>{if(e.target===dialog)close();});dialog.addEventListener('cancel',e=>{if(new URLSearchParams(location.search).has('item')){e.preventDefault();close();}});
add?.addEventListener('click',()=>{form.reset();form.elements.namedItem('id_item').value='0';document.getElementById('editor-dialog-title').textContent='Agregar elemento';form.elements.namedItem('orden').value=String(<?=count($items)+1?>);updateIcon();updateVisibility();dialog.showModal();});
if(new URLSearchParams(location.search).has('item'))dialog.showModal();
})();
</script></body></html>
